#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
v4: Additive merge of ~100 SRD 5.2 canonical spells to close coverage gap from
110 → 242 → ~342 (target ~360 SRD 5.2).

PARSER-V3-BUG-FIX: Uses the CORRECTED bilingual pattern. Each spell uses nested
bilingual dicts `{"en":..., "es":...}` for localized fields (name, school,
description). NO split-key `description_en`/`description_es` (that bug was patched
post-hoc on data files but the v3 source still has it; v4 doesn't repeat it).

Additive merge keyed on `id`: existing spells are preserved verbatim; only NEW
ids are appended. Source data → `localize()` walker → flat per-language output
matching the existing shape.
"""
from __future__ import annotations
