  # ─────────────────────────── CANTRIPS (level 0) ────────────────────────
  {"id":"sword_burst","name":{"en":"Sword Burst","es":"Ráfaga de espadas"},"level":0,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"Self (5-foot radius)","duration":"Instantaneous","components":"V","classes":["Sorcerer","Warlock","Wizard"],"description_en":"You create a momentary circle of spectral blades that sweep around you. Each creature within range must succeed on a Dexterity saving throw or take 1d6 force damage.","description_es":"Creas un círculo instantáneo de hojas espectrales que barren a tu alrededor. Cada criatura en el radio debe superar una salvación de Destreza o recibir 1d6 de fuerza.","savingThrow":"Dexterity","areaOfEffect":"5-foot radius"},
  {"id":"lightning_lure","name":{"en":"Lightning Lure","es":"Señuelo relampagueante"},"level":0,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"Self (15-foot radius)","duration":"Instantaneous","components":"V","classes":["Sorcerer","Wizard"],"description_en":"You create a lash of lightning energy that strikes one creature you can see within range. Strength save or pulled 10 feet toward you and 1d8 lightning damage.","description_es":"Creas un latigazo de energía relámpago que golpea a una criatura visible en tu alcance. Fuerza o es atraída 3 m hacia ti y recibe 1d8 eléctrico.","savingThrow":"Strength","areaOfEffect":"15-foot radius"},
  {"id":"mind_sliver","name":{"en":"Mind Sliver","es":"Esquirla mental"},"level":0,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"60 feet","duration":"1 round","components":"V","classes":["Sorcerer","Warlock","Wizard"],"description_en":"You drive a disorienting spike of psychic energy into the mind of one creature. Int save or 1d6 psychic damage; next save it makes before end of turn is at disadvantage.","description_es":"Clavas una astilla desorientadora de energía psíquica en la mente de una criatura. Inteligencia o 1d6 psíquico; la próxima salvación antes del final del turno tiene desventaja.","savingThrow":"Intelligence"},
