  {"id":"conjure_woodland_beings","name":{"en":"Conjure Woodland Beings","es":"Convocar seres del bosque"},"level":4,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"60 feet","duration":"Concentration, up to 1 hour","components":"V, S, M (a handful of moss from a fey grove)","classes":["Druid","Ranger"],"description_en":"Summon fey creatures or treants (CR 1/2 or lower; 2 per slot above 4). They follow your commands.","description_es":"Invocas criaturas feéricas o treants (CR ≤ 1/2; 2 por ranura mayor). Te obedecen."},
  {"id":"death_ward","name":{"en":"Death Ward","es":"Protección contra muerte"},"level":4,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"Touch","duration":"8 hours","components":"V, S","classes":["Cleric","Paladin"],"description_en":"Touch a creature: the first time it would drop to 0 HP, it instead drops to 1 HP and other instant-death effects are negated once.","description_es":"Tocas a una criatura: la primera vez que caería a 0 pg, cae a 1 pg; efectos de muerte instantánea se niegan una vez."},
  {"id":"divination","name":{"en":"Divination","es":"Adivinación"},"level":4,"school":{"en":"Divination (Ritual)","es":"Adivinación (Ritual)"},"castingTime":"Action","range":"Self","duration":"Instantaneous","components":"V, S, M","classes":["Cleric","Wizard"],"description_en":"Contact a deity or proxy for a single piece of knowledge (specific location/item/event).","description_es":"Contactas a una deidad o intermediario para obtener un dato único (ubicación/objeto/evento específico).","materials":"Holy water and blessed incense"},
  {"id":"elemental_bane","name":{"en":"Elemental Bane","es":"Perdición elemental"},"level":4,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"90 feet","duration":"Concentration, up to 1 minute","components":"V, S, M (a bit of sulfur)","classes":["Bard","Druid","Sorcerer","Wizard","Warlock"],"description_en":"Choose 1-cube-foot flammable object in range (multiple per slot above 4). Each creature in contact at casting: Con save or disadvantage against one damage type, taking 2d6 extra damage next hit.","description_es":"Elige objetos combustibles dentro del cubo (varios por slot mayor). Cada criatura en contacto al lanzar: Constitución o desventaja contra un tipo de daño y 2d6 extra al impactar.","savingThrow":"Constitution"},
  {"id":"mordenkainens_faithful_hound","name":{"en":"Mordenkainen's Faithful Hound","es":"Sabueso fiel de Mordenkainen"},"level":4,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"30 feet","duration":"8 hours","components":"V, S, M (a small silver whistle)","classes":["Wizard"],"description_en":"A spectral hound appears in an unoccupied space you choose. It has advantage on Wisdom (Perception) checks and Charisma (Investigation) checks, magically barks when Small or larger creatures within 30 ft without your permission, and attacks intruders.","description_es":"Un sabueso espectral aparece en un espacio libre a 9 m. Ventaja en Supervivencia e Investigación, ladra mágicamente ante criaturas Pequeñas o mayores a 9 m sin tu permiso, y ataca intrusos."},
  {"id":"mordenkainens_private_sanctum","name":{"en":"Mordenkainen's Private Sanctum","es":"Santuario privado de Mordenkainen"},"level":4,"school":{"en":"Abjuration (Ritual)","es":"Abjuración (Ritual)"},"castingTime":"10 minutes","range":"120 feet","duration":"24 hours","components":"V, S, M","classes":["Wizard"],"description_en":"Setup a 100-ft cube magical warding. Sound can't pass through; divination spells can't target/penetrate; creatures in the cube can't be charmed/frightened.","description_es":"Creas un cubo de 30 m de protección mágica. El sonido no lo atraviesa; conjuros de adivinación no apuntan/penetran; criaturas dentro no pueden ser encantadas ni asustadas.","materials":"An 800-pound black pearl carved with sigils","areaOfEffect":"100-foot cube"},
  {"id":"otilukes_resilient_sphere","name":{"en":"Otiluke's Resilient Sphere","es":"Esfera resistente de Otiluke"},"level":4,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"30 feet","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Wizard"],"description_en":"A sphere of shimmering force (10-ft radius) surrounds a creature or object. The target stays inside, has 3 AC and 50 temp HP; sphere is invulnerable to nonmagical damage.","description_es":"Una esfera de fuerza titilante (radio 3 m) rodea a una criatura/objeto. El objetivo queda dentro; CA 3 y 50 pg temp; esfera invulnerable a daño no mágico.","materials":"A hemispherical piece of crystal and a matching hemispherical piece of adamantine"},
  {"id":"stone_shape","name":{"en":"Stone Shape","es":"Forma de piedra"},"level":4,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"Touch","duration":"Instantaneous","components":"V, S, M (a tiny chisel and a small hammer)","classes":["Artificer","Druid","Wizard"],"description_en":"Touch a stone object Medium or smaller; reshape it to your purposes. As much as one 5-ft cube.","description_es":"Tocas un objeto de piedra Mediano o menor; lo reformas a tu voluntad. Hasta un cubo de 1,5 m."},

  # ────────────────────────────── LEVEL 5 ──────────────────────────────────
  {"id":"awaken","name":{"en":"Awaken","es":"Despertar"},"level":5,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"8 hours","range":"Touch","duration":"Instantaneous","components":"V, S, M (an agate and herbs consumed)","classes":["Bard","Druid"],"description_en":"Touch a beast or plant with INT ≤ 4. It gains INT, ability to speak one language, become the caster's devoted ally for 30 days.","description_es":"Tocas a una bestia o planta con INT ≤ 4. Gana INT, capacidad de hablar un idioma, se vuelve aliado devoto durante 30 días."},
  {"id":"bigbys_hand","name":{"en":"Bigby's Hand","es":"Mano de Bigby"},"level":5,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 1 minute","components":"V, S, M (a snail shell and a glove)","classes":["Wizard"],"description_en":"A large disembodied magic hand appears. Forceful push: Strength save or 20 ft away. Grip: hand grapple, Strength save or held. Interposing hand: +5 AC.","description_es":"Aparece una mano mágica grande. Empuje: Fuerza o 6 m de empuje. Agarre: la mano atrapa; Fuerza o sostienes. Interposición: +5 CA."},
  {"id":"contact_other_plane","name":{"en":"Contact Other Plane","es":"Contactar otro plano"},"level":5,"school":{"en":"Divination (Ritual)","es":"Adivinación (Ritual)"},"castingTime":"Action","range":"Self","duration":"Instantaneous","components":"V, M (a set of three questions writing on parchment; the inks made from exotic materials)","classes":["Warlock","Wizard"],"description_en":"You mentally contact an otherworldly entity. Ask up to 5 questions; answers are slanted toward the entity's goals. Risk of madness (6 INT save per question).","description_es":"Contactas mentalmente a una entidad de otro mundo. Hasta 5 preguntas; respuestas orientadas a sus metas. Riesgo de locura (6 Inteligencia por pregunta)."},
  {"id":"contagion","name":{"en":"Contagion","es":"Contagio"},"level":5,"school":{"en":"Necromancy","es":"Nigromancia"},"castingTime":"Action","range":"Touch","duration":"7 days","components":"V, S","classes":["Cleric","Druid"],"description_en":"Touch a creature: Con save or contract a disease (Blinding Sickness, Filth Fever, Flesh Rot, Mindfire, or Seizure) for the duration.","description_es":"Tocas a una criatura: Constitución o contrae una enfermedad (Ceguera, Fiebre, Podredumbre, Fuego Mental, Convulsión) durante la duración.","savingThrow":"Constitution"},
  {"id":"dream","name":{"en":"Dream","es":"Sueño"},"level":5,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"1 minute","range":"Unlimited","duration":"8 hours","components":"V, S, M (a handful of sand, silvered or not)","classes":["Bard","Warlock","Wizard"],"description_en":"Send a message to another creature through a dream. Doesn't require target to know you. Triggers Wis save vs. nightmare effect.","description_es":"Envías un mensaje a otra criatura a través de un sueño. No requiere que el objetivo te conozca. Sabiduría para resistir a pesadilla."},
  {"id":"hallow","name":{"en":"Hallow","es":"Sagrar"},"level":5,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"24 hours","range":"Touch","duration":"Until dispelled","components":"V, S, M","classes":["Cleric","Paladin"],"description_en":"Inscribe divine magic into a location. Celestials/elementals/fey/fiends/undead have disadvantage on attack rolls and ability checks within 60 ft. Can chain effect (deny entry, etc.).","description_es":"Inscribes magia divina en una ubicación. Celestiales/elementales/feéricos/infernales/no-muertos tienen desventaja en ataques y pruebas dentro de 18 m. Encadena texto.","materials":"Herbs, oils, and incense worth at least 1,000 gp"},
  {"id":"mislead","name":{"en":"Mislead","es":"Engaño"},"level":5,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"Action","range":"Self","duration":"Concentration, up to 1 hour","components":"S","classes":["Bard","Warlock","Wizard"],"description_en":"You become invisible and an illusory duplicate of you appears at your original space. As a bonus action, you can move the duplicate up to 30 ft.","description_es":"Te vuelves invisible y aparece un duplicado ilusorio en tu posición. Como acción adicional, mueves el duplicado hasta 9 m."},
  {"id":"modify_memory","name":{"en":"Modify Memory","es":"Modificar memoria"},"level":5,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"30 feet","duration":"Concentration, up to 1 minute","components":"V, S","classes":["Bard","Wizard"],"description_en":"Wis save or you alter up to 10 minutes of target's memory in 1 minute increments (Wis save each minute). With higher slots, longer.","description_es":"Sabiduría o modificas hasta 10 minutos de su memoria en incrementos de 1 minuto (Sabiduría cada min). A mayor slot, más largo.","savingThrow":"Wisdom"},
  {"id":"reincarnate","name":{"en":"Reincarnate","es":"Reencarnar"},"level":5,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"1 hour","range":"Touch","duration":"Instantaneous","components":"V, S, M (rare oils worth 100 gp consumed)","classes":["Druid"],"description_en":"Touch a dead humanoid dead at most 10 days. Returns with new humanoid body (DM rolls random race).","description_es":"Tocas a un humanoide muerto hace ≤ 10 días. Regresa con cuerpo humanoide nuevo (el DM aleatoriza la raza)."},
  {"id":"seeming","name":{"en":"Seeming","es":"Apariencia"},"level":5,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"Action","range":"30 feet","duration":"8 hours","components":"V, S","classes":["Bard","Sorcerer","Wizard"],"description_en":"You change the appearance of any number of creatures within range. Each creature must succeed on a Charisma save or have their appearance changed.","description_es":"Cambias la apariencia de cualquier número de criaturas a 9 m. Cada una debe hacer salvación de Carisma o ve cambiada su apariencia.","savingThrow":"Charisma"},
  {"id":"steel_wind_strike","name":{"en":"Steel Wind Strike","es":"Golpe del viento de acero"},"level":5,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"30 feet","duration":"Instantaneous","components":"V, S, M (a melee weapon worth at least 1 cp)","classes":["Ranger","Wizard"],"description_en":"You flourish a melee weapon: 5 attacks on the same turn against 5 different creatures within range within 30 ft of each other. 4d10 force damage each on hit (instead of the weapon's normal damage).","description_es":"Floreas un arma cuerpo a cuerpo: 5 ataques en el mismo turno contra 5 criaturas distintas dentro de 9 m entre sí. 4d10 de fuerza por impacto (en vez del daño del arma)."},
  {"id":"swift_quiver","name":{"en":"Swift Quiver","es":"Carcaj veloz"},"level":5,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Bonus action","range":"Touch","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Ranger"],"description_en":"Up to two arrows (or bolts/quarrels) form magically on your person each turn. As a part of your turn, you can fire one at an attack bonus + your spellcasting modifier (1d6+modifier damage).","description_es":"Hasta dos flechas (o virotes/proyectiles) surgen mágicamente cada turno. Como parte de tu turno, disparas uno con bonus + modificador de conjuro (1d6+modificador).","materials":"A shortbow or a longbow"},
  {"id":"transmute_rock","name":{"en":"Transmute Rock","es":"Transmutar roca"},"level":5,"school":{"en":"Transmutation (Ritual)","es":"Transmutación (Ritual)"},"castingTime":"Action","range":"120 feet","duration":"Until dispelled","components":"V, S, M (clay and water)","classes":["Druid","Wizard"],"description_en":"Choose a 40-ft cube of earth/stone/sand within range. Transform all of it into mud (difficult terrain) or sand (loose texture, hard to walk).","description_es":"Elige un cubo de 12 m de tierra/piedra/arena en el alcance. Transmutas todo en barro (terreno difícil) o arena suelta.","areaOfEffect":"40-foot cube"},

  # ────────────────────────────── LEVEL 6 ──────────────────────────────────
  {"id":"bones_of_the_earth","name":{"en":"Bones of the Earth","es":"Huesos de la tierra"},"level":6,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"120 feet","duration":"1 minute","components":"V, S","classes":["Wizard"],"description_en":"Push up pillars of earth/stone. Up to 3 pillars (1 CR: 1d6 bludgeoning; 2-CR pillars trap Medium creatures).","description_es":"Levantas pilares de tierra/piedra. Hasta 3 pilares (1 CR: 1d6 contundente; de 2 CR atrapan criaturas Medianas)."},
  {"id":"drawmijs_instant_summons","name":{"en":"Drawmij's Instant Summons","es":"Convocación instantánea de Drawmij"},"level":6,"school":{"en":"Conjuration (Ritual)","es":"Conjuración (Ritual)"},"castingTime":"1 minute","range":"Touch","duration":"Until dispelled","components":"V, S, M (a gem worth at least 1,000 gp, inscribed with specific mark)","classes":["Wizard"],"description_en":"Touch an object (≤ 10 ft any dimension) and inscribe a glyph on the gem. As action, speak word + crush sapphire -> teleport object to your hand.","description_es":"Tocas un objeto (≤ 3 m cualquier dimensión) y grabas un glifo en la gema. Como acción, dices la palabra + rompes zafiro -> teletransportas el objeto a tu mano."},
  {"id":"eyebite","name":{"en":"Eyebite","es":"Mordedura ocular"},"level":6,"school":{"en":"Necromancy","es":"Nigromancia"},"castingTime":"Action","range":"Self","duration":"Concentration, up to 1 minute","components":"V, S","classes":["Bard","Sorcerer","Warlock","Wizard"],"description_en":"Your eyes become anointed. Each creature in 30-ft cone (action). Pick an effect: Asleep, Panicked, or Sickened (Wis save each round).","description_es":"Tus ojos se ungen. Cada criatura en un cono (acción). Elige un efecto: dormido, asustado, o enfermo (Sabiduría cada turno).","savingThrow":"Wisdom","areaOfEffect":"30-foot cone"},
  {"id":"flesh_to_stone","name":{"en":"Flesh to Stone","es":"Carne a piedra"},"level":6,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"60 feet","duration":"Concentration, up to 1 minute","components":"V, S, M (a pinch of lime, water, and earth)","classes":["Warlock","Wizard"],"description_en":"A creature you can see makes a Constitution save; on fail, begins to turn to stone (restrained at end of turn). Repeat on your turn; 3rd fails = petrified.","description_es":"Una criatura visible hace salvación de Constitución; falla: comienza a petrificarse (apresada al final del turno). Repite en tu turno; 3er fallo = petrificada.","savingThrow":"Constitution"},
  {"id":"move_earth","name":{"en":"Move Earth","es":"Mover tierra"},"level":6,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 2 hours","components":"V, S","classes":["Druid","Sorcerer","Wizard"],"description_en":"Choose an area of terrain no larger than 40 ft on each side. Shapes earth/stone/sand as you walk in 10-ft cubes; area is heavily obscured until reshaped.","description_es":"Eliges un terreno ≤ 12 m por lado. Le das forma caminando en cubos de 3 m; área oculta visión hasta reformarla.","areaOfEffect":"40-foot cube"},
  {"id":"tashas_otherworldly_guise","name":{"en":"Tasha's Otherworldly Guise","es":"Apariencia de otro mundo de Tasha"},"level":6,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Bonus action","range":"Self","duration":"Concentration, up to 1 minute","components":"V, S, M (an artifact)","classes":["Sorcerer","Warlock","Wizard"],"description_en":"Clad yourself in a magical suit of different celestial/fiend/whatever form. AC=13+Dex, radiant/fire/lightning/necrotic/frost damage 1d6/turn, fly 40 ft, gain 5 radiant (otherworldly) damage to attacks.","description_es":"Te revistes con armadura mágica de celestial/infernal/etc. CA=13+Destreza, daño luminoso/fuego/relámpago/necrótico/frío 1d6/turno, vuelo 12 m, +5 daño radiante a ataques."},
  {"id":"word_of_recall","name":{"en":"Word of Recall","es":"Palabra de regreso"},"level":6,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"5 feet","duration":"Instantaneous","components":"V","classes":["Cleric"],"description_en":"You and up to 5 willing creatures within 5 feet of you instantly teleport to a previously designated sanctuary.","description_es":"Tú y hasta 5 criaturas voluntarias a 1,5 m os teletransportáis al instante a un santuario previamente designado."},

  # ────────────────────────────── LEVEL 7 ──────────────────────────────────
  {"id":"abi_dalzims_horrid_wilting","name":{"en":"Abi-Dalzim's Horrid Wilting","es":"Marchitamiento horrible de Abi-Dalzim"},"level":7,"school":{"en":"Necromancy","es":"Nigromancia"},"castingTime":"Action","range":"150 feet","duration":"Instantaneous","components":"V, S, M (a bit of sponge)","classes":["Sorcerer","Wizard"],"description_en":"Necrotic water strikes the targets. Each in a 30-ft cube: Con save or 12d8 necrotic; half on success (plants/water elementals automatically fail).","description_es":"Agua necrótica golpea a los objetivos. En un cubo de 9 m: Constitución o 12d8 necrótico; mitad con éxito (plantas y elementales de agua fallan auto).","savingThrow":"Constitution","areaOfEffect":"30-foot cube"},
  {"id":"draconic_transformation","name":{"en":"Draconic Transformation","es":"Transformación dracónica"},"level":7,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Bonus action","range":"Self","duration":"Concentration, up to 10 minutes","components":"V, S, M (dragon scales)","classes":["Druid","Wizard"],"description_en":"Sprout draconic features. Melee attacks deal 4d6 elemental damage; breath weapon (60-ft cone) 4d6. Right of \"Dr.\" Resistances.","description_es":"Brota rasgos dracónicos. Ataques cuerpo a cuerpo: 4d6 elemental; arma de aliento (cono 18 m): 4d6. Resistencia elemental."},
  {"id":"dream_of_the_blue_veil","name":{"en":"Dream of the Blue Veil","es":"Sueño del Velo Azul"},"level":7,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"20 feet","duration":"Concentration, up to 1 hour","components":"V","classes":["Bard","Wizard"],"description_en":"Up to 8 willing creatures take a journey to another realm. Wis save vs. interrupting the journey; once ended, must travel back.","description_es":"Hasta 8 criaturas voluntarias viajan a otro reino. Sabiduría puede interrumpir el viaje; una vez terminado, vuelven."},
  {"id":"magnificent_mansion","name":{"en":"Mordenkainen's Magnificent Mansion","es":"Mansión magnífica de Mordenkainen"},"level":7,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"300 feet","duration":"24 hours","components":"V, S, M (a miniature ivory door, a small silver key, and a miniature marble arch worth 500 gp)","classes":["Wizard"],"description_en":"Casts a 50-ft cube extradimensional dwelling. Has up to 100 rooms, plus food, drink, stables, servants, and terrain.","description_es":"Creas una mansión extradimensional de cubo 15 m. Hasta 100 habitaciones, comida/bebida, establos, sirvientes y exteriores."},
  {"id":"mirage_arcane","name":{"en":"Mirage Arcane","es":"Espejismo arcano"},"level":7,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"10 minutes","range":"Sight","duration":"10 days","components":"V, S","classes":["Bard","Druid","Wizard"],"description_en":"You make terrain in an area up to 1 mile square look, sound, smell, and feel like some other type. Disguises structures, creatures, and spell effects.","description_es":"Haces que el terreno en un área de hasta 1,6 km cuadrados se vea, suene, huela como otro tipo. Disimula estructuras, criaturas y efectos."},
  {"id":"power_word_pain","name":{"en":"Power Word Pain","es":"Palabra de poder: dolor"},"level":7,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"60 feet","duration":"Instantaneous","components":"V","classes":["Sorcerer","Warlock","Wizard"],"description_en":"Speak a word of power. Up to 200 HP creature makes Con save or drops to 0 hit points and is unconscious. Above 200, save halves HP and rest.","description_es":"Pronuncias una palabra de poder. Criatura hasta 200 pg hace salvación de Constitución o cae a 0 pg y queda inconsciente."},
  {"id":"whirlwind","name":{"en":"Whirlwind","es":"Torbellino"},"level":7,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"300 feet","duration":"Concentration, up to 1 minute","components":"V, M (a piece of straw)","classes":["Druid","Wizard"],"description_en":"A whirlwind of air moves to a point within range. Each Medium or smaller creature in the area makes a Strength save or takes 10d6 bludgeoning and is launched 20 ft.","description_es":"Un torbellino se mueve hacia un punto en el alcance. Criaturas Medianas o menores hacen salvación de Fuerza o reciben 10d6 contundente y son lanzadas 6 m.","savingThrow":"Strength"},

  # ────────────────────────────── LEVEL 8 ──────────────────────────────────
  {"id":"animal_shapes","name":{"en":"Animal Shapes","es":"Formas animales"},"level":8,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"30 feet","duration":"Concentration, up to 24 hours","components":"V, S","classes":["Bard","Druid"],"description_en":"Magically transform willing creatures into beasts with CR 4 or lower for the duration (or +2 with slot 9).","description_es":"Conviertes criaturas voluntarias en bestias con CR ≤ 4 (+2 con slot 9) durante la duración."},
  {"id":"befuddlement","name":{"en":"Befuddlement","es":"Confusión"},"level":8,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"150 feet","duration":"Concentration, up to 1 minute","components":"V, S, M (a wasp's nest)","classes":["Bard","Druid","Wizard"],"description_en":"One creature of your choice makes Con save or is reduced to an early stage of its life (becomes a child), losing class/racial features, gaining (-4 Strength, -4 Charisma, -2 Constitution).","description_es":"Una criatura hace salvación de Constitución o retrocede a una etapa infantil; pierde rasgos de clase/raza, gana (-4 Fuerza, -4 Carisma, -2 Constitución).","savingThrow":"Constitution"},
  {"id":"clenched_fist","name":{"en":"Clenched Fist","es":"Puño cerrado"},"level":8,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"Self","duration":"Concentration, up to 1 minute","components":"V, S, M (a fistful of iron filings)","classes":["Wizard"],"description_en":"A giant clenched fist appears. As a bonus action it punches: each creature in 5 ft makes STR save or 2d6 force and pushed 5 ft.","description_es":"Aparece un puño gigante. Acción adicional para golpear: cada criatura en 1,5 m: Fuerza o 2d6 fuerza y empujada 1,5 m.","savingThrow":"Strength","areaOfEffect":"5-foot radius"},
  {"id":"glibness","name":{"en":"Glibness","es":"Labia"},"level":8,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"Self","duration":"1 hour","components":"V","classes":["Bard","Warlock","Wizard"],"description_en":"For the duration, when you make a Charisma check, you can replace your roll with a 15. You can't benefit from this on a target for a few days.","description_es":"Por la duración, al hacer pruebas de Carisma puedes sustituir tu tirada por un 15. No efectos sobre el mismo objetivo en días siguientes."},
  {"id":"illusory_dragon","name":{"en":"Illusory Dragon","es":"Dragón ilusorio"},"level":8,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 1 minute","components":"V, S","classes":["Bard","Wizard"],"description_en":"A huge translucent dragon appears. Each creature in radius makes Int save or takes 4d12 psychic and limited. As a bonus action, can move 60 ft.","description_es":"Aparece un dragón translúcido enorme. Cada criatura en radio hace Int o 4d12 psíquico. Acción adicional para moverlo 18 m.","savingThrow":"Intelligence","areaOfEffect":"60-foot radius"},
  {"id":"telepathy","name":{"en":"Telepathy","es":"Telepatía"},"level":8,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"120 feet","duration":"24 hours","components":"V, S, M (a pair of linked silver rings)","classes":["Wizard"],"description_en":"Establish a telepathic communication with a creature you can see. Can send/receive thoughts in any language.","description_es":"Estableces comunicación telepática con una criatura visible a 18 m. Puedes enviar/recibir pensamientos en cualquier idioma."},

  # ────────────────────────────── LEVEL 9 ──────────────────────────────────
